# --- RFC 6901 JSON Pointer field indexing ---------------------------------

# Query value type tags persisted in a JsonSearchReceipt, keeping the JSON
# scalar kinds apart (True is not 1, "" is not the string "null", ...).
_JSON_TAG_STRING = 0
_JSON_TAG_INTEGER = 1
_JSON_TAG_FLOAT = 2
_JSON_TAG_TRUE = 3
_JSON_TAG_NULL = 4
_JSON_TAG_FALSE = 5

# Sentinel for "this payload yields no queryable scalar at the pointer".
_JSON_MISSING = object()

# Kind names accepted by the find_where "type" leaf, matched
# case-sensitively: integers and finite floats are both "number", booleans
# are not numbers, and the empty array/object are "array"/"object".
_JSON_TYPE_KINDS = frozenset(
    {"null", "boolean", "number", "string", "array", "object"}
)

# Scalar kinds that may appear in a JsonSearchIndex group.
_JSON_INDEX_KINDS = frozenset(
    {
        _JSON_TAG_STRING,
        _JSON_TAG_INTEGER,
        _JSON_TAG_FLOAT,
        _JSON_TAG_TRUE,
        _JSON_TAG_NULL,
        _JSON_TAG_FALSE,
    }
)

# Kinds whose single value is encoded as the empty blob (true / false / null).
_JSON_INDEX_EMPTY_KINDS = frozenset(
    {_JSON_TAG_TRUE, _JSON_TAG_FALSE, _JSON_TAG_NULL}
)


class _JsonDuplicateMember(ValueError):
    """Internal: a JSON object repeated a member name."""


def _decode_json_index_numeric(kind: int, key: bytes) -> Any:
    """Decode a canonical integer/float bucket key back to its number.

    Structural validity (ASCII, finite) is enforced by
    :func:`_check_json_index_bucket_key`; this only re-parses.
    """
    if kind == _JSON_TAG_INTEGER:
        return int(key.decode("ascii"))
    return float(key.decode("ascii"))


def _check_json_index_bucket_key(kind: int, key: Any) -> None:
    """Validate one bucket key blob for its group's kind."""
    if not isinstance(key, bytes):
        raise TypeError("bucket key must be bytes")
    if kind in _JSON_INDEX_EMPTY_KINDS:
        if key:
            raise ValueError(
                "a boolean or null bucket key must be the empty blob"
            )
        return
    if kind == _JSON_TAG_STRING:
        # Strings carry arbitrary text; the key must be valid UTF-8.
        try:
            key.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("string bucket key must be valid UTF-8") from error
        return
    try:
        text = key.decode("ascii")
    except UnicodeDecodeError as error:
        raise ValueError("numeric bucket key must be ASCII") from error
    if kind == _JSON_TAG_INTEGER:
        digits = text[1:] if text[:1] == "-" else text
        if not digits or any(ch not in "0123456789" for ch in digits):
            raise ValueError("integer bucket key must be canonical ASCII decimal")
    elif kind == _JSON_TAG_FLOAT:
        try:
            value = float(text)
        except ValueError as error:
            raise ValueError("float bucket key must be an ASCII number") from error
        if not math.isfinite(value):
            raise ValueError("float bucket key must be finite")
        if repr(value).encode("ascii") != key:
            raise ValueError("float bucket key must be the canonical repr spelling")


def _check_json_value(value: Any) -> None:
    """Validate a find_json / json_search_receipt scalar query value."""
    if isinstance(value, bool) or isinstance(value, str) or value is None:
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("value must be a finite number")
        return
    raise TypeError("value must be str, int, float, bool or None")


def _check_json_threshold(value: Any) -> None:
    """Validate a find_where numeric-comparison threshold.

    Only a non-boolean ``int`` or a finite ``float`` is accepted: booleans
    are not numbers for this comparison, and a non-finite threshold would
    make the comparison degenerate.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("threshold must be an int or a float")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("threshold must be a finite number")


def _parse_json_pointer(pointer: Any) -> tuple[str, ...]:
    """Parse an RFC 6901 JSON Pointer into its tuple of unescaped tokens.

    The empty string is the root pointer and yields ``()``. A non-``str``
    pointer raises TypeError; a non-empty pointer that does not start with
    ``/`` or a reference token carrying an escape other than ``~0`` /
    ``~1`` raises ValueError.
    """
    if not isinstance(pointer, str):
        raise TypeError("pointer must be a string")
    if pointer == "":
        return ()
    if not pointer.startswith("/"):
        raise ValueError("a non-empty JSON Pointer must start with '/'")
    tokens: list[str] = []
    for raw in pointer.split("/")[1:]:
        if "~" not in raw:
            tokens.append(raw)
            continue
        decoded: list[str] = []
        index = 0
        while index < len(raw):
            char = raw[index]
            if char == "~":
                if index + 1 >= len(raw) or raw[index + 1] not in "01":
                    raise ValueError("JSON Pointer escape must be '~0' or '~1'")
                decoded.append("~" if raw[index + 1] == "0" else "/")
                index += 2
            else:
                decoded.append(char)
                index += 1
        tokens.append("".join(decoded))
    return tuple(tokens)


def _json_pointer_canonical(tokens: tuple[str, ...]) -> str:
    """Canonical RFC 6901 spelling of parsed pointer tokens."""
    if not tokens:
        return ""
    return "".join(
        "/" + token.replace("~", "~0").replace("/", "~1") for token in tokens
    )


def _json_reject_duplicates(pairs: Any) -> dict:
    document: dict = {}
    for key, value in pairs:
        if key in document:
            raise _JsonDuplicateMember(f"duplicate JSON object member {key!r}")
        document[key] = value
    return document


def _json_reject_constant(value: str) -> Any:
    # RFC 8259 has no NaN/Infinity; Python's json accepts them by default.
    raise ValueError(f"{value} is not valid JSON")


def _strict_json_document(payload: bytes) -> Any:
    """Decode and parse strict UTF-8 JSON bytes, or ``_JSON_MISSING``.

    A single strict parse shared by every pointer bound to the same
    payload: the bytes must decode as UTF-8 and parse as JSON with no
    repeated object member name at any depth and no non-finite number.
    Every failure mode (bad UTF-8, invalid JSON, a repeated member)
    counts as one parse attempt and yields the ``_JSON_MISSING``
    sentinel, exactly like :func:`_json_scalar_at`.
    """
    try:
        text = payload.decode("utf-8")
        return json.loads(
            text,
            object_pairs_hook=_json_reject_duplicates,
            parse_constant=_json_reject_constant,
        )
    except (UnicodeDecodeError, ValueError):
        return _JSON_MISSING


def _json_pointer_resolve(document: Any, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens against an already-parsed document.

    Same traversal rules as :func:`_json_scalar_at`: a missing
    member/element, traversal through a non-container, an array token
    that is non-numeric (``-`` included), has leading zeroes or is
    out of range, or an addressed object/array rather than a scalar
    yields ``_JSON_MISSING``.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return _JSON_MISSING
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return _JSON_MISSING
            index = int(token)
            if index >= len(current):
                return _JSON_MISSING
            current = current[index]
        else:
            return _JSON_MISSING
    if current is None or isinstance(current, (str, bool, int, float)):
        return current
    return _JSON_MISSING


def _json_pointer_exists(document: Any, tokens: tuple[str, ...]) -> bool:
    """Whether parsed pointer tokens resolve to any value in a document.

    Same traversal rules as :func:`_json_pointer_resolve` — a missing
    member/element, traversal through a non-container, or an array token
    that is non-numeric (``-`` included), has leading zeroes or is out of
    range does not hit — but the addressed value may be anything: null, a
    scalar, an object or an array all count as present, and the empty
    token tuple addresses the whole document.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return False
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return False
            index = int(token)
            if index >= len(current):
                return False
            current = current[index]
        else:
            return False
    return True


def _json_pointer_value(document: Any, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens to the addressed value of any type.

    Same traversal rules as :func:`_json_pointer_exists` — a missing
    member/element, traversal through a non-container, or an array token
    that is non-numeric (``-`` included), has leading zeroes or is out of
    range yields the ``_JSON_MISSING`` sentinel — but the addressed value
    itself is returned whatever it is: null, a scalar, an object or an
    array, and the empty token tuple addresses the whole document.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return _JSON_MISSING
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return _JSON_MISSING
            index = int(token)
            if index >= len(current):
                return _JSON_MISSING
            current = current[index]
        else:
            return _JSON_MISSING
    return current


def _json_type_kind_of(value: Any) -> str:
    """The find_where "type" kind name of an addressed JSON value.

    Booleans are checked before integers (``bool`` subclasses ``int``) and
    are never numbers; integers and floats are both "number" — the strict
    parse already rejected every non-finite float.
    """
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"


def _json_scalar_at(payload: bytes, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens against strict UTF-8 JSON bytes.

    Returns the addressed scalar, or the ``_JSON_MISSING`` sentinel when
    the payload is not strict UTF-8 JSON, repeats an object member name at
    any depth, carries a non-finite number, the pointer traverses a missing
    member/element or a non-container, indexes an array with a non-numeric
    (``-`` included), leading-zero or out-of-range token, or the addressed
    value is an object or array rather than a scalar.
    """
    document = _strict_json_document(payload)
    if document is _JSON_MISSING:
        return _JSON_MISSING
    return _json_pointer_resolve(document, tokens)


def _json_scalar_matches(found: Any, value: Any) -> bool:
    """Whether an addressed JSON scalar equals a query, per JSON kind.

    Strings, booleans and null only match their own kind; ints and floats
    are both JSON numbers and compare by numeric value (a JSON ``true`` is
    never the number 1).
    """
    if value is None:
        return found is None
    if isinstance(value, bool):
        return isinstance(found, bool) and found == value
    if isinstance(value, str):
        return isinstance(found, str) and found == value
    # int and float are both JSON numbers: numeric equality across the two.
    return (
        isinstance(found, (int, float))
        and not isinstance(found, bool)
        and found == value
    )

